CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]

def polymod(values):
    chk = 1
    for v in values:
        b = chk >> 25
        chk = (chk & 0x1ffffff) << 5 ^ v
        for i in range(5):
            chk ^= GEN[i] if ((b >> i) & 1) else 0
    return chk

def hrp_expand(hrp):
    return [ord(x) >> 5 for x in hrp] + [0] + [ord(x) & 31 for x in hrp]

def create_checksum(hrp, data):
    values = hrp_expand(hrp) + data
    pm = polymod(values + [0,0,0,0,0,0]) ^ 1
    return [(pm >> 5 * (5 - i)) & 31 for i in range(6)]

def encode(hrp, data5):
    combined = data5 + create_checksum(hrp, data5)
    return hrp + '1' + ''.join([CHARSET[d] for d in combined])

def convertbits(data, frombits, tobits, pad=True):
    acc = 0; bits = 0; ret = []
    maxv = (1 << tobits) - 1
    max_acc = (1 << (frombits + tobits - 1)) - 1
    for value in data:
        if value < 0 or (value >> frombits):
            return None
        acc = ((acc << frombits) | value) & max_acc
        bits += frombits
        while bits >= tobits:
            bits -= tobits
            ret.append((acc >> bits) & maxv)
    if pad:
        if bits:
            ret.append((acc << (tobits - bits)) & maxv)
    elif bits >= frombits or ((acc << (tobits - bits)) & maxv):
        return None
    return ret

def enc_bytes(hrp, b):
    return encode(hrp, convertbits(list(b), 8, 5))

def decode(bechstr):
    """returns (hrp, data5) no case checks"""
    pos = bechstr.rfind('1')
    hrp = bechstr[:pos]
    data5 = [CHARSET.find(c) for c in bechstr[pos+1:]]
    return hrp, data5

def dec_bytes(bechstr):
    hrp, d = decode(bechstr.lower())
    return hrp, bytes(convertbits(d[:-6], 5, 8, False) or [])
